def sim_fall(I):
    n=len(I); G=[[0]*n for _ in range(n)]
    g=[row[:] for row in I]
    changed=True
    while changed:
        changed=False
        for i in range(n-1,-1,-1):
            for j in range(n-1,-1,-1):
                if g[i][j]:
                    ni,nj=i-1,j-1
