                if ty==anch[0]-h and tx==anch[1]-w:
                    sc=(ty,tx); break
                dist=(abs(ty-anch[0]+h), abs(tx-anch[1]+w))
                if best is None or dist<best[0]: best=(dist,sc)
            if best: break
        if best:
            dist,sc=best
            for y,x in shape: R[sc[0]+y][sc[1]+x]=c
            settled|= {(sc[0]+y,sc[1]+x) for y,x in shape}
    return R,cs,order,settled
